"""Audit and report existing evaluated results. No score, rank, or economic rerun."""
from pathlib import Path
import json,hashlib,math
import pandas as pd,numpy as np
O=Path(__file__).resolve().parent;B=O.parents[2]/'mobile_candidate_response_v1'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(n):return pd.read_csv(O/n)
def table(df):
    z=df.copy()
    for c in z:
        if pd.api.types.is_float_dtype(z[c]):z[c]=z[c].map(lambda x:'UNKNOWN' if pd.isna(x) else f'{x:.6f}')
    return '\n'.join(['| '+' | '.join(map(str,z.columns))+' |','| '+' | '.join(['---']*len(z.columns))+' |']+['| '+' | '.join(map(str,r))+' |' for r in z.itertuples(index=False,name=None)])
def pct(df,cols):
    z=df.copy()
    for c in cols:z[c]*=100
    return z
# Audit baseline path numbers against the previous saved test without recomputing labels.
a=read('ANNUAL_OUTCOMES.csv');old=pd.read_csv(B/'ANNUAL_SAME_K_OUTCOMES.csv');checks=[]
for r in a[a.strategy=='ORIGINAL_PVR'].itertuples():
    q=old[(old.account==r.account)&old.year.eq(r.year)&old.strategy.eq('ORIGINAL_PVR')].iloc[0];H=r.horizon
    assert r.complete==q[f'complete{H}']
    for current,prior in [(r.path_win_rate,q[f'positive_ret{H}']),(r.event_mean_return,q[f'event_mean_ret{H}']),(r.mean_close_MAE,q[f'mean_mae{H}'])]:assert abs(current-prior)<1e-12
    checks.append(dict(account=r.account,year=r.year,horizon=H,old_baseline_metric_exact_within_1e_12=True))
# Floating summation order can create +/-1e-18 on unchanged same-member days.
# Only direction counts are repaired; all reported return/MAE differences and means stay unchanged.
pair=read('PAIRED_DATE_DETAILS.csv');nochange=pair[~pair.changed]
max_same_member_abs=float(nochange.diff_event_mean_return.abs().max());assert max_same_member_abs<1e-12
roundoff=[]
for groups,name in [(['account','year','horizon'],'MATCHED_COMPLETE_DATE_RESULTS.csv'),(['account','quarter','horizon'],'QUARTER_PAIRED_RESULTS.csv'),(['account','market_state','horizon'],'MARKET_PAIRED_RESULTS.csv'),(['account','horizon'],'OVERALL_PAIRED_RESULTS.csv')]:
    z=read(name);raw=O/(name.replace('.csv','_BEFORE_DIRECTION_ROUNDOFF_AUDIT.csv'));raw.write_bytes((O/name).read_bytes())
    for key,g in pair.groupby(groups):
        mask=pd.Series(True,index=z.index)
        for col,value in zip(groups,key):mask&=z[col].eq(value)
        v=g[g.both_all_complete].diff_event_mean_return
        oldcounts=z.loc[mask,['positive_return_diff_dates','negative_return_diff_dates','equal_return_diff_dates']].values[0].tolist()
        counts=[int(v.gt(1e-12).sum()),int(v.lt(-1e-12).sum()),int(v.abs().le(1e-12).sum())]
        z.loc[mask,['positive_return_diff_dates','negative_return_diff_dates','equal_return_diff_dates']]=counts
        if oldcounts!=counts:roundoff.append(dict(file=name,key=key,old_counts=oldcounts,counts=counts))
    z.to_csv(O/name,index=False)
(O/'NUMERIC_DIRECTION_AUDIT.json').write_text(json.dumps(dict(max_same_membership_abs_return_difference=max_same_member_abs,count_tolerance=1e-12,changes=roundoff,means_and_financial_values_unchanged=True,ranking_unchanged=True),indent=2))
